from pathlib import Path
import openpyxl

_WIRE_IDS = ('INTL-2026-0214', 'INTL-2026-0219', 'INTL-2026-0223', 'INTL-2026-0228')
_AUDIT_HEADER_KEYWORDS = ('slack query', 'approver', 'dual auth', 'exception code', 'note')

def _audit_fill_score(path):
    """Count populated audit (AGENT-FILL) cells on the audited wire rows.

    Returns -1 when the file cannot be opened or holds no recognizable wire
    rows; otherwise the number of non-empty cells in audit columns (Slack
    Query Used, Approver *, Dual Auth, Exception Code, Notes) across rows
    whose Wire ID cell exactly matches one of the audited wire IDs."""
    try:
        wb = openpyxl.load_workbook(path, data_only=True)
        ws = wb.active
    except Exception:
        return -1
    header_row = None
    headers = []
    for r in range(1, min(ws.max_row, 10) + 1):
        row_vals = [str(c.value).strip().lower() if c.value is not None else '' for c in ws[r]]
        if any('wire id' in h for h in row_vals) or any('approver' in h for h in row_vals):
            header_row = r
            headers = row_vals
            break
    if header_row is None:
        return -1
    audit_cols = [i for i, h in enumerate(headers) if h and any(k in h for k in _AUDIT_HEADER_KEYWORDS)]
    wire_id_col = next((i for i, h in enumerate(headers) if 'wire' in h and 'id' in h), 0)
    score = 0
    found_wire_row = False
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        wid = str(row[wire_id_col]).strip().upper() if wire_id_col < len(row) and row[wire_id_col] is not None else ''
        if wid in _WIRE_IDS:
            found_wire_row = True
            for ci in audit_cols:
                if ci < len(row) and row[ci] is not None and str(row[ci]).strip() != '':
                    score += 1
    if not found_wire_row:
        return -1
    return score

def _find_wire_workbook(workspace_path):
    """Select the workbook to grade: the agent's populated wire audit log
    wherever it lives. Prefer the xlsx whose AGENT-FILL columns are populated
    for the audited wire rows (e.g. a dated workpaper saved per SOP 1.4),
    breaking ties toward the seeded Wire Population filename; fall back to
    the wire/population filename match when nothing is populated."""
    xlsx_files = [f for f in sorted(Path(workspace_path).glob('**/*.xlsx'), key=lambda p: p.name)
                  if not f.name.startswith('~$')]
    if not xlsx_files:
        return None

    def name_rank(f):
        nl = f.name.lower()
        if 'wire' in nl and 'population' in nl:
            return 0
        if 'wire' in nl:
            return 1
        return 2

    best = None
    best_key = None
    for f in xlsx_files:
        score = _audit_fill_score(f)
        if score > 0:
            key = (-score, name_rank(f), f.name)
            if best_key is None or key < best_key:
                best = f
                best_key = key
    if best is not None:
        return best
    for rank in (0, 1):
        for f in xlsx_files:
            if name_rank(f) == rank:
                return f
    return None

def verify(workspace_path, external_services_path=None):
    target = _find_wire_workbook(workspace_path)
    if target is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No Wire Population xlsx file found in workspace.'}
    try:
        wb = openpyxl.load_workbook(target, data_only=True)
        ws = wb.active
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to open workbook: {e}'}

    # The rubric says headers are in row 3. Try rows 1, 2, and 3 to find the header row.
    header_row = None
    wire_id_col = None
    dual_auth_col = None

    for candidate_row in [3, 1, 2, 4, 5]:
        try:
            headers = [str(cell.value).strip() if cell.value is not None else '' for cell in ws[candidate_row]]
        except Exception:
            continue
        temp_wire_id_col = None
        temp_dual_auth_col = None
        for i, h in enumerate(headers):
            hl = h.lower()
            if ('wire' in hl and ('id' in hl or 'ref' in hl or 'num' in hl)) or 'wire id' in hl or 'reference' in hl:
                temp_wire_id_col = i
            if 'dual' in hl and 'auth' in hl:
                temp_dual_auth_col = i
        # Also try matching on just column content patterns
        if temp_wire_id_col is None:
            for i, h in enumerate(headers):
                if 'intl' in h.upper() or h.upper().startswith('WIRE'):
                    temp_wire_id_col = i
                    break
        if temp_dual_auth_col is not None:
            header_row = candidate_row
            wire_id_col = temp_wire_id_col
            dual_auth_col = temp_dual_auth_col
            break

    if dual_auth_col is None:
        # Fallback: scan all columns across all rows for the header
        all_headers_info = []
        for r in range(1, min(ws.max_row + 1, 10)):
            row_vals = [str(cell.value).strip() if cell.value is not None else '' for cell in ws[r]]
            all_headers_info.append(f'Row {r}: {row_vals}')
        return {'pass': False, 'score': 0.0, 'feedback': f'Could not find Dual Auth Confirmed column. Scanned rows: {"  |  ".join(all_headers_info)}'}

    if wire_id_col is None:
        wire_id_col = 0  # default to first column

    expected = {
        'INTL-2026-0214': 'Y',
        'INTL-2026-0219': 'Y',
        'INTL-2026-0223': 'N',
        'INTL-2026-0228': 'N',
    }
    results = {}
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        if len(row) <= max(wire_id_col, dual_auth_col):
            continue
        wire_id = str(row[wire_id_col]).strip() if row[wire_id_col] is not None else ''
        if wire_id in expected:
            val = str(row[dual_auth_col]).strip().upper() if row[dual_auth_col] is not None else ''
            results[wire_id] = val

    failures = []
    for wire_id, exp_val in expected.items():
        actual_val = results.get(wire_id, 'NOT FOUND')
        if actual_val != exp_val:
            failures.append(f'{wire_id}: expected {exp_val}, got {actual_val}')

    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Dual Auth Confirmed mismatches: {failures}. Found results: {results}'}
    return {'pass': True, 'score': 1.0, 'feedback': f'Dual Auth Confirmed values correct for all four wire IDs (headers in row {header_row}). Found: {results}'}

