            if 'TRE900' not in val.upper().replace(' ', '').replace('-', ''):
                failures.append(f'{wid}: expected TRE-900 in exception code, got "{val}"')
    for wid in must_not_have:
        val = results.get(wid, '')
        if 'TRE-900' in val.upper().replace(' ', '') or 'TRE900' in val.upper().replace(' ', '').replace('-', ''):
            failures.append(f'{wid}: TRE-900 should NOT be present, got "{val}"')

    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Exception Code Applied issues: {failures}. Header row detected: {header_row}. Results found: {results}'}
    return {'pass': True, 'score': 1.0, 'feedback': f'Exception Code Applied correct for all four wire IDs. Header row: {header_row}. Found: {results}'}

