    try:
        wb = openpyxl.load_workbook(target, data_only=True)
        ws = wb.active
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to open workbook: {e}'}

    # The rubric says headers are in row 3. Try rows 1-5 to find headers.
    header_row = None
    headers = []
    for candidate_row in [3, 1, 2, 4, 5]:
        row_cells = list(ws[candidate_row])
        candidate_headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in row_cells]
        if any('approver' in h for h in candidate_headers):
            headers = candidate_headers
            header_row = candidate_row
            break

    if header_row is None:
        row_cells = list(ws[3])
        headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in row_cells]
        header_row = 3

    def find_col(keywords):
        for i, h in enumerate(headers):
            if all(k.lower() in h for k in keywords):
                return i
        return None

    # Try to find wire ID column
    wire_id_col = find_col(['wire', 'id'])
    if wire_id_col is None:
        wire_id_col = find_col(['wire'])
    if wire_id_col is None:
        wire_id_col = find_col(['intl'])
    if wire_id_col is None:
        wire_id_col = find_col(['id'])
    if wire_id_col is None:
        wire_id_col = 0

    ap1_name_col = find_col(['approver', '1', 'name'])
    ap1_text_col = find_col(['approver', '1', 'text'])
    ap2_name_col = find_col(['approver', '2', 'name'])
    ap2_text_col = find_col(['approver', '2', 'text'])

    # Try alternative matching with broader keywords
    if None in [ap1_name_col, ap1_text_col, ap2_name_col, ap2_text_col]:
        for i, h in enumerate(headers):
            if 'approver' in h and '1' in h and 'name' in h and ap1_name_col is None:
                ap1_name_col = i
            elif 'approver' in h and '1' in h and ('text' in h or 'comment' in h or 'response' in h or 'status' in h or 'decision' in h) and ap1_text_col is None:
                ap1_text_col = i
            elif 'approver' in h and '2' in h and 'name' in h and ap2_name_col is None:
                ap2_name_col = i
            elif 'approver' in h and '2' in h and ('text' in h or 'comment' in h or 'response' in h or 'status' in h or 'decision' in h) and ap2_text_col is None:
                ap2_text_col = i

    missing_cols = [name for name, col in [('Approver 1 Name', ap1_name_col), ('Approver 1 Text', ap1_text_col), ('Approver 2 Name', ap2_name_col), ('Approver 2 Text', ap2_text_col)] if col is None]
    if missing_cols:
        return {'pass': False, 'score': 0.0, 'feedback': f'Could not find columns: {missing_cols}. Headers found in row {header_row}: {headers}'}

    def name_matches(actual, expected_dotted):
        """Check if actual name matches expected, with or without dot, case insensitive.
        E.g., 'claire.overton' should match 'claireoverton', 'claire.overton', 'Claire.Overton', 'Claire Overton', etc.
        """
        actual_clean = actual.lower().strip()
        # Remove dots and spaces for comparison
        actual_nodot = actual_clean.replace('.', '').replace(' ', '')
        expected_nodot = expected_dotted.lower().replace('.', '').replace(' ', '')
        # Check: exact with dot, without dot, or contained in
        if expected_dotted.lower() in actual_clean:
            return True
        if expected_nodot in actual_nodot:
            return True
        return False

    def text_matches(actual):
        """Check if the text contains 'approved' (case insensitive), being lenient."""
        return 'approved' in actual.lower().strip()

    expected = {
        'INTL-2026-0214': {'ap1_name': 'claire.overton', 'ap2_name': 'rachel.kim'},
        'INTL-2026-0219': {'ap1_name': 'peter.walsh', 'ap2_name': 'nadine.cole'},
    }
    failures = []
    found = {}

    data_start_row = header_row + 1

    for row in ws.iter_rows(min_row=data_start_row, values_only=False):
        row_vals = [cell.value for cell in row]
        wire_id_val = row_vals[wire_id_col] if wire_id_col < len(row_vals) else None
        wire_id = str(wire_id_val).strip() if wire_id_val is not None else ''
        if wire_id in expected:
            ap1n = str(row_vals[ap1_name_col]).strip() if ap1_name_col < len(row_vals) and row_vals[ap1_name_col] is not None else ''
            ap1t = str(row_vals[ap1_text_col]).strip() if ap1_text_col < len(row_vals) and row_vals[ap1_text_col] is not None else ''
            ap2n = str(row_vals[ap2_name_col]).strip() if ap2_name_col < len(row_vals) and row_vals[ap2_name_col] is not None else ''
            ap2t = str(row_vals[ap2_text_col]).strip() if ap2_text_col < len(row_vals) and row_vals[ap2_text_col] is not None else ''
            found[wire_id] = {'ap1_name': ap1n, 'ap1_text': ap1t, 'ap2_name': ap2n, 'ap2_text': ap2t}
            exp = expected[wire_id]
            if not name_matches(ap1n, exp['ap1_name']):
                failures.append(f'{wire_id}: Approver 1 Name expected to contain "{exp["ap1_name"]}" (with or without dot), got "{ap1n}"')
            if not text_matches(ap1t):
                failures.append(f'{wire_id}: Approver 1 Text expected to contain "Approved.", got "{ap1t}"')
            if not name_matches(ap2n, exp['ap2_name']):
                failures.append(f'{wire_id}: Approver 2 Name expected to contain "{exp["ap2_name"]}" (with or without dot), got "{ap2n}"')
            if not text_matches(ap2t):
                failures.append(f'{wire_id}: Approver 2 Text expected to contain "Approved.", got "{ap2t}"')

    for wid in expected:
        if wid not in found:
            failures.append(f'{wid}: row not found in workbook (searched from row {data_start_row} onward with wire ID in column {wire_id_col})')

    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Approver field mismatches: {failures}'}
    return {'pass': True, 'score': 1.0, 'feedback': f'Approver fields correct for INTL-2026-0214 and INTL-2026-0219. Found: {found}'}

