    found_wire_row = False
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        wid = str(row[wire_id_col]).strip().upper() if wire_id_col < len(row) and row[wire_id_col] is not None else ''
        if wid in _WIRE_IDS:
            found_wire_row = True
            for ci in audit_cols:
                if ci < len(row) and row[ci] is not None and str(row[ci]).strip() != '':
                    score += 1
    if not found_wire_row:
        return -1
    return score

def _find_wire_workbook(workspace_path):
    """Select the workbook to grade: the agent's populated wire audit log
    wherever it lives. Prefer the xlsx whose AGENT-FILL columns are populated
    for the audited wire rows (e.g. a dated workpaper saved per SOP 1.4),
    breaking ties toward the seeded Wire Population filename; fall back to
    the wire/population filename match when nothing is populated."""
    xlsx_files = [f for f in sorted(Path(workspace_path).glob('**/*.xlsx'), key=lambda p: p.name)
                  if not f.name.startswith('~$')]
    if not xlsx_files:
        return None

    def name_rank(f):
        nl = f.name.lower()
        if 'wire' in nl and 'population' in nl:
            return 0
        if 'wire' in nl:
            return 1
        return 2

    best = None
    best_key = None
    for f in xlsx_files:
        score = _audit_fill_score(f)
        if score > 0:
            key = (-score, name_rank(f), f.name)
            if best_key is None or key < best_key:
                best = f
                best_key = key
    if best is not None:
        return best
    for rank in (0, 1):
        for f in xlsx_files:
            if name_rank(f) == rank:
                return f
    return None

def verify(workspace_path, external_services_path=None):
    target = _find_wire_workbook(workspace_path)
    if target is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No Wire Population xlsx file found.'}
    try:
        wb = openpyxl.load_workbook(target, data_only=True)
        ws = wb.active
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to open workbook: {e}'}

    # The rubric says headers are in row 3, so try rows 1-5 to find headers
    header_row = None
    headers = []
    for candidate_row in [3, 1, 2, 4, 5]:
        if candidate_row > ws.max_row:
            continue
        candidate_headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in ws[candidate_row]]
        has_approver = any('approver' in h for h in candidate_headers)
        if has_approver:
            headers = candidate_headers
            header_row = candidate_row
            break
    if header_row is None:
        header_row = 3
        if header_row <= ws.max_row:
            headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in ws[header_row]]
        else:
            return {'pass': False, 'score': 0.0, 'feedback': f'Worksheet has only {ws.max_row} rows, cannot find header row.'}

    wire_id_col = None
    ap1_name_col = None
    ap1_text_col = None
    ap2_name_col = None
    ap2_text_col = None
    notes_cols = []
    all_approver_text_cols = []
    all_approver_name_cols = []

    for i, h in enumerate(headers):
        # Wire ID column detection
        if wire_id_col is None and (
            ('wire' in h and ('id' in h or 'ref' in h or 'num' in h)) or
            h.startswith('intl') or 'wire id' in h or 'reference' in h or
            'transaction' in h or 'wire_id' in h
        ):
            wire_id_col = i
        # Approver 1 Name
        if 'approver' in h and '1' in h and 'name' in h and ap1_name_col is None:
            ap1_name_col = i
        # Approver 1 Text
        if 'approver' in h and '1' in h and ('text' in h or 'comment' in h or 'response' in h) and ap1_text_col is None:
            ap1_text_col = i
        # Approver 2 Name
        if 'approver' in h and '2' in h and 'name' in h and ap2_name_col is None:
            ap2_name_col = i
        # Approver 2 Text
        if 'approver' in h and '2' in h and ('text' in h or 'comment' in h or 'response' in h) and ap2_text_col is None:
            ap2_text_col = i
        # Track all approver text and name columns
        if 'approver' in h and ('text' in h or 'comment' in h or 'response' in h):
            all_approver_text_cols.append(i)
        if 'approver' in h and 'name' in h:
            all_approver_name_cols.append(i)
        # Notes columns
        if 'note' in h or 'comment' in h or 'remark' in h or 'flag' in h or 'finding' in h:
            notes_cols.append(i)

    # If wire_id_col not found, try first column
    if wire_id_col is None:
        wire_id_col = 0

    missing = [name for name, col in [
        ('Approver 1 Name', ap1_name_col),
        ('Approver 1 Text', ap1_text_col),
        ('Approver 2 Name', ap2_name_col)
    ] if col is None]
    if missing:
        return {'pass': False, 'score': 0.0, 'feedback': f'Missing columns: {missing}. Headers found in row {header_row}: {headers}'}

    def cell_val(row_tuple, col_idx):
        """Safely get cell value from row tuple."""
        if col_idx is not None and col_idx < len(row_tuple) and row_tuple[col_idx] is not None:
            return str(row_tuple[col_idx]).strip()
        return ''

    def name_matches(val, target_name):
        """Check if val matches the target name, with or without dot, case insensitive.
        e.g., 'claire.overton' matches 'claireoverton', 'claire.overton', 'Claire.Overton', etc."""
        val_clean = val.lower().replace('.', '').replace(' ', '')
        target_clean = target_name.lower().replace('.', '').replace(' ', '')
        return target_clean in val_clean

    def is_absent(val):
        """True when the value clearly denotes a missing/absent approver.
        The SOP prescribes no exact workbook token (Template B-3: 'OR state
        Missing dual approval'), so accept any value that unambiguously
        encodes absence, e.g. 'NONE — no second reply' or
        'N/A (no second approver)'."""
        v = val.strip().lower()
        if v in ('', 'n/a', 'na', 'n/ a', 'missing', 'none', 'null', '-', '--', 'empty', '—', '–'):
            return True
        if ('missing' in v or 'no second' in v or 'not applicable' in v
                or 'no approver' in v or 'no qualifying' in v or 'not found' in v):
            return True
        first = re.split(r'[\s—–\-:;,(]+', v, maxsplit=1)[0].strip('.')
        return first in ('n/a', 'na', 'none', 'null', 'empty', 'blank', 'missing')

    failures = []
    found_0223 = False
    found_0228 = False

    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        if row is None:
            continue
        wire_id_val = row[wire_id_col] if wire_id_col < len(row) else None
        wire_id = str(wire_id_val).strip() if wire_id_val is not None else ''

        # ---- INTL-2026-0223 ----
        # Match the wire row by exact Wire ID only (audit-summary/footer lines
        # that merely mention the wire ID are not wire rows); first match wins.
        if wire_id.upper() == 'INTL-2026-0223' and not found_0223:
            found_0223 = True
            ap1n = cell_val(row, ap1_name_col).lower()
            ap1t = cell_val(row, ap1_text_col)

            # Check Approver 1 Name contains claire.overton (with or without dot)
            if not name_matches(ap1n, 'claire.overton'):
                failures.append(f'INTL-2026-0223: Approver 1 Name should contain claire.overton (case insensitive, with/without dot), got: "{ap1n}"')

            # Check Approver 1 Text contains 'Approved.' (loose: check for 'approved')
            if 'approved' not in ap1t.lower():
                failures.append(f'INTL-2026-0223: Approver 1 Text should contain "Approved.", got: "{ap1t}"')

            # Check steven.ford appears in the intended evidence columns
            # (approver name/text or notes), not merely anywhere in the row
            evidence_cols = all_approver_name_cols + all_approver_text_cols + notes_cols
            steven_found = False
            for ci in evidence_cols:
                cv = cell_val(row, ci).lower()
                if name_matches(cv, 'steven.ford'):
                    steven_found = True
                    break
            if not steven_found:
                failures.append(f'INTL-2026-0223: steven.ford not found in any approver or notes column')

            # Check LGTM appears in the intended evidence columns
            lgtm_found = False
            for ci in evidence_cols:
                cv = cell_val(row, ci).lower()
                if 'lgtm' in cv:
                    lgtm_found = True
                    break
            if not lgtm_found:
                failures.append(f'INTL-2026-0223: "LGTM" not found in any approver or notes column')

            # Approver 2 fields must assert either the non-qualifying LGTM
            # responder (steven.ford) or a missing second approver — never a
            # different person or a qualifying "Approved" response
            ap2n_0223 = cell_val(row, ap2_name_col)
            ap2t_0223 = cell_val(row, ap2_text_col) if ap2_text_col is not None else ''
            if name_matches(ap2n_0223, 'steven.ford'):
                if 'approved' in ap2t_0223.lower() and 'lgtm' not in ap2t_0223.lower():
                    failures.append(f'INTL-2026-0223: Approver 2 Text asserts "Approved" for steven.ford, but his response was "LGTM" (non-qualifying), got: "{ap2t_0223}"')
            elif not is_absent(ap2n_0223):
                failures.append(f'INTL-2026-0223: Approver 2 Name should name steven.ford (non-qualifying LGTM responder) or denote a missing second approver, got: "{ap2n_0223}"')

        # ---- INTL-2026-0228 ----
        # Exact Wire ID match only; first match wins (see 0223 note above)
        if wire_id.upper() == 'INTL-2026-0228' and not found_0228:
            found_0228 = True
            ap1n = cell_val(row, ap1_name_col).lower()
            ap1t = cell_val(row, ap1_text_col)
            ap2n = cell_val(row, ap2_name_col)

            # Check Approver 1 Name contains claire.overton
            if not name_matches(ap1n, 'claire.overton'):
                failures.append(f'INTL-2026-0228: Approver 1 Name should contain claire.overton (case insensitive, with/without dot), got: "{ap1n}"')

            # Check Approver 1 Text contains 'Approved.'
            if 'approved' not in ap1t.lower():
                failures.append(f'INTL-2026-0228: Approver 1 Text should contain "Approved.", got: "{ap1t}"')

            # Approver 2 Name must be blank or clearly denote absence
            if not is_absent(ap2n):
                failures.append(f'INTL-2026-0228: Approver 2 Name should be blank/N/A/Missing, got: "{ap2n}"')

    if not found_0223:
        failures.append('INTL-2026-0223 row not found in workbook')
    if not found_0228:
        failures.append('INTL-2026-0228 row not found in workbook')

    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Issues found: {failures}'}
    return {
        'pass': True,
        'score': 1.0,
        'feedback': (
            f'INTL-2026-0223 and INTL-2026-0228 approver fields verified correctly. '
            f'Headers found in row {header_row}. File: {target.name}'
        )
    }

from pathlib import Path
import openpyxl
import re

_WIRE_IDS = ('INTL-2026-0214', 'INTL-2026-0219', 'INTL-2026-0223', 'INTL-2026-0228')
_AUDIT_HEADER_KEYWORDS = ('slack query', 'approver', 'dual auth', 'exception code', 'note')

def _audit_fill_score(path):
    """Count populated audit (AGENT-FILL) cells on the audited wire rows.

    Returns -1 when the file cannot be opened or holds no recognizable wire
    rows; otherwise the number of non-empty cells in audit columns (Slack
    Query Used, Approver *, Dual Auth, Exception Code, Notes) across rows
    whose Wire ID cell exactly matches one of the audited wire IDs."""
    try:
        wb = openpyxl.load_workbook(path, data_only=True)
        ws = wb.active
    except Exception:
        return -1
    header_row = None
    headers = []
    for r in range(1, min(ws.max_row, 10) + 1):
        row_vals = [str(c.value).strip().lower() if c.value is not None else '' for c in ws[r]]
        if any('wire id' in h for h in row_vals) or any('approver' in h for h in row_vals):
            header_row = r
            headers = row_vals
            break
    if header_row is None:
        return -1
    audit_cols = [i for i, h in enumerate(headers) if h and any(k in h for k in _AUDIT_HEADER_KEYWORDS)]
    wire_id_col = next((i for i, h in enumerate(headers) if 'wire' in h and 'id' in h), 0)
    score = 0
    found_wire_row = False
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        wid = str(row[wire_id_col]).strip().upper() if wire_id_col < len(row) and row[wire_id_col] is not None else ''
        if wid in _WIRE_IDS:
            found_wire_row = True
            for ci in audit_cols:
                if ci < len(row) and row[ci] is not None and str(row[ci]).strip() != '':
                    score += 1
    if not found_wire_row:
        return -1
    return score

def _find_wire_workbook(workspace_path):
    """Select the workbook to grade: the agent's populated wire audit log
    wherever it lives. Prefer the xlsx whose AGENT-FILL columns are populated
    for the audited wire rows (e.g. a dated workpaper saved per SOP 1.4),
    breaking ties toward the seeded Wire Population filename; fall back to
    the wire/population filename match when nothing is populated."""
    xlsx_files = [f for f in sorted(Path(workspace_path).glob('**/*.xlsx'), key=lambda p: p.name)
                  if not f.name.startswith('~$')]
    if not xlsx_files:
        return None

    def name_rank(f):
        nl = f.name.lower()
        if 'wire' in nl and 'population' in nl:
            return 0
        if 'wire' in nl:
            return 1
        return 2

    best = None
    best_key = None
    for f in xlsx_files:
        score = _audit_fill_score(f)
        if score > 0:
            key = (-score, name_rank(f), f.name)
            if best_key is None or key < best_key:
                best = f
                best_key = key
    if best is not None:
        return best
    for rank in (0, 1):
        for f in xlsx_files:
            if name_rank(f) == rank:
                return f
    return None

def verify(workspace_path, external_services_path=None):
    target = _find_wire_workbook(workspace_path)
    if target is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No Wire Population xlsx file found.'}
    try:
        wb = openpyxl.load_workbook(target, data_only=True)
        ws = wb.active
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to open workbook: {e}'}

    # The rubric says headers are in row 3, so try rows 1, 2, and 3 for headers
    header_row = None
    headers = []
    for candidate_row in [3, 1, 2, 4]:
        candidate_headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in ws[candidate_row]]
        has_slack = any('slack' in h and 'query' in h for h in candidate_headers)
        if has_slack:
            headers = candidate_headers
            header_row = candidate_row
            break
    if header_row is None:
        # Fallback: try all rows up to 10
        for candidate_row in range(1, 11):
            candidate_headers = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in ws[candidate_row]]
            has_slack = any('slack' in h and 'query' in h for h in candidate_headers)
            if has_slack:
                headers = candidate_headers
                header_row = candidate_row
                break
    if header_row is None:
        all_headers_tried = []
        for r in range(1, 6):
            row_vals = [str(cell.value).strip().lower() if cell.value is not None else '' for cell in ws[r]]
            all_headers_tried.append(f'Row {r}: {row_vals}')
        return {'pass': False, 'score': 0.0, 'feedback': f'Could not find Slack Query Used column in any header row. Tried rows: {chr(10).join(all_headers_tried)}'}

    wire_id_col = None
    slack_query_col = None
    for i, h in enumerate(headers):
        if ('wire' in h and ('id' in h or 'ref' in h or 'num' in h)) or h.startswith('intl') or 'transaction' in h or h == 'id':
            wire_id_col = i
        if 'slack' in h and 'query' in h:
            slack_query_col = i

    if slack_query_col is None:
        return {'pass': False, 'score': 0.0, 'feedback': f'Could not find Slack Query Used column. Headers (row {header_row}): {headers}'}

    # If we couldn't identify wire id column, try first column or scan for one containing 'INTL'
    if wire_id_col is None:
        # Try to find a column that has INTL-2026 values
        for row in ws.iter_rows(min_row=header_row + 1, max_row=header_row + 5, values_only=True):
            for ci, cell_val in enumerate(row):
                if cell_val and 'INTL-2026' in str(cell_val):
                    wire_id_col = ci
                    break
            if wire_id_col is not None:
                break
        if wire_id_col is None:
            wire_id_col = 0  # fallback to first column

    found_row = False
    for row in ws.iter_rows(min_row=header_row + 1, values_only=True):
        wire_id = str(row[wire_id_col]).strip() if row[wire_id_col] is not None else ''
        if wire_id == 'INTL-2026-0219':
            found_row = True
            val = str(row[slack_query_col]).strip() if slack_query_col < len(row) and row[slack_query_col] is not None else ''
            val_lower = val.lower()

            # Accept only the exact Slack channel-query operator or an
            # explicit reference to prescribed query 2/3. A prose mention of
            # treasury-wires is not evidence that either query was run.
            has_channel_query = bool(re.search(
                r'(?<![A-Za-z0-9_])in:#treasury-wires(?![A-Za-z0-9_-])',
                val_lower,
            ))
            has_query_marker = bool(re.search(
                r'\bquery\s*(?:\(\s*[23]\s*\)(?!\w)|[23]\b)',
                val_lower,
            ))
            if has_channel_query:
                return {'pass': True, 'score': 1.0, 'feedback': f'INTL-2026-0219 Slack Query Used correctly contains in:#treasury-wires: "{val}"'}
            if has_query_marker:
                return {'pass': True, 'score': 1.0, 'feedback': f'INTL-2026-0219 Slack Query Used correctly references query 2 or 3: "{val}"'}

            # Check it's not ONLY the first query
            normalized = val.lower().strip()
            only_first = normalized in ['has:link intl-2026-0219', 'has:link intl-2026-0219']
            if only_first or (normalized and 'in:' not in normalized and '#' not in normalized and 'query' not in normalized and 'treasury' not in normalized):
                return {'pass': False, 'score': 0.0, 'feedback': f'INTL-2026-0219 Slack Query Used does not reflect query (2) or (3) with in:#treasury-wires. Got: "{val}"'}

            return {'pass': False, 'score': 0.0, 'feedback': f'INTL-2026-0219 Slack Query Used does not clearly indicate query (2) or (3) with in:#treasury-wires. Got: "{val}"'}

    if not found_row:
        return {'pass': False, 'score': 0.0, 'feedback': f'INTL-2026-0219 row not found in workbook. Wire ID column index: {wire_id_col}, header row: {header_row}'}

from pathlib import Path
import json


def extract_text(node):
    if isinstance(node, str):
        return node
    if isinstance(node, dict):
        if node.get('type') == 'text':
            return node.get('text', '')
        return ' '.join(extract_text(c) for c in node.get('content', []))
    if isinstance(node, list):
        return ' '.join(extract_text(i) for i in node)
    return str(node)


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path not provided; cannot check jira_state.json.'}
    jira_path = Path(external_services_path) / 'jira_state.json'
    if not jira_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'jira_state.json not found in external_services_path.'}
    try:
        with open(jira_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to parse jira_state.json: {e}'}

    issues = data.get('issues', data) if isinstance(data, dict) else {}
    all_comments = data.get('comments', {}) if isinstance(data, dict) else {}
    token = 'status=verified'   # exact verification marker from SOP 3.3 Happy path
    failures = []

    def find_issue(key):
        issue = issues.get(key)
        if issue is None:
            for k, v in issues.items():
                if isinstance(v, dict) and v.get('key', '').upper() == key.upper():
                    return v
        return issue

    def has_verify_comment(key):
        comments = all_comments.get(key, [])
        comments = comments if isinstance(comments, list) else []
        for c in comments:
            body = extract_text(c.get('body', '') if isinstance(c, dict) else c)
            if token in body:
                return True
        return False

    # 0214 and 0219 (dual-auth confirmed) MUST carry a 'status=verified' comment
    for key in ['OPS-1', 'OPS-2']:
        if find_issue(key) is None:
            failures.append(f'{key}: issue not found in jira_state.json')
            continue
        if not has_verify_comment(key):
            failures.append(f"{key}: no comment contains exact token '{token}', expected one")

    # 0223 and 0228 (exception wires) MUST NOT carry a 'status=verified' comment
    for key in ['OPS-3', 'OPS-4']:
        if find_issue(key) is None:
            failures.append(f'{key}: issue not found in jira_state.json')
            continue
        if has_verify_comment(key):
            failures.append(f"{key}: has a '{token}' comment but this is an exception wire — must not be marked verified")

    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Jira verification-comment issues: {failures}'}
    return {'pass': True, 'score': 1.0, 'feedback': "OPS-1 and -0219 carry a 'status=verified' comment; -0223 and -0228 do not."}

from pathlib import Path
import json

def _items(value):
    if value is None:
        return []
    if isinstance(value, list):
        return value
    if isinstance(value, dict) and isinstance(value.get('comments'), list):
        return value['comments']
    return [value]

def _contains_tre900(value):
    if isinstance(value, str):
        return 'TRE-900' in value
    try:
        return 'TRE-900' in json.dumps(value)
    except (TypeError, ValueError):
        return False

def _issue_comments(data, key, issue, fields):
    comments = []

    # Jira's persisted state keeps comments in a top-level map keyed by the
    # issue key. Also recognize an issue id/key alias when one is present.
    top_comments = data.get('comments', {}) if isinstance(data, dict) else {}
    if isinstance(top_comments, dict):
        references = [key, issue.get('key'), issue.get('id')]
        seen = set()
        for reference in references:
            if reference is None or str(reference) in seen:
                continue
            seen.add(str(reference))
            if reference in top_comments:
                comments.extend(_items(top_comments[reference]))

    # Some Jira serializers embed comments on the issue or in fields.comment.
    for value in (
        issue.get('comments'),
        issue.get('comment'),
        fields.get('comments'),
        fields.get('comment'),
    ):
        comments.extend(_items(value))
    return comments

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path not provided.'}
    jira_path = Path(external_services_path) / 'jira_state.json'
    if not jira_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'jira_state.json not found.'}
    try:
        with open(jira_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to parse jira_state.json: {e}'}
    issues = data.get('issues', data) if isinstance(data, dict) else {}
    target_keys = ['OPS-3', 'OPS-4']
    failures = []
    for key in target_keys:
        issue = issues.get(key)
        if issue is None:
            for k, v in issues.items():
                if isinstance(v, dict) and v.get('key', '').upper() == key.upper():
                    issue = v
                    break
        if issue is None:
            failures.append(f'{key}: not found in jira_state.json')
            continue
        found_tre900 = False
        fields = issue.get('fields', {})
        if not isinstance(fields, dict):
            fields = {}

        # Labels are persisted under fields.labels in Jira issue objects.
        labels = fields.get('labels', [])
        if isinstance(labels, list) and any('TRE-900' in str(label) for label in labels):
            found_tre900 = True

        # Comments may be top-level keyed entries or embedded on the issue.
        if not found_tre900:
            found_tre900 = any(
                _contains_tre900(comment)
                for comment in _issue_comments(data, key, issue, fields)
            )

        # Only explicitly named custom/exception/code fields count. In
        # particular, fields.description is never searched.
        if not found_tre900:
            for field_key, field_val in fields.items():
                normalized_key = str(field_key).lower()
                if normalized_key == 'description':
                    continue
                is_named_custom_field = (
                    normalized_key.startswith('customfield_')
                    or 'custom' in normalized_key
                    or 'exception' in normalized_key
                    or 'code' in normalized_key
                )
                if is_named_custom_field and _contains_tre900(field_val):
                    found_tre900 = True
                    break
        if not found_tre900:
            failures.append(f'{key}: TRE-900 not found in labels, comments, or custom fields (description alone does not count)')
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'TRE-900 application issues: {failures}'}
    return {'pass': True, 'score': 1.0, 'feedback': 'TRE-900 correctly applied via labels/comments/fields for INTL-2026-0223 and INTL-2026-0228.'}

