from pathlib import Path
import json
import re

_ANALYST_FIELD_RE = re.compile(r'analyst\s*[:\-–—]\s*([^|\n]*)', re.IGNORECASE)
# Named people in the task universe (Slack seed users; Jira CCO Diana Walsh).
# None of them is the acting junior operations analyst, so Template B-4's
# Analyst field must not identify any of them.
_OTHER_PERSON_NAMES = ('diana walsh', 'thomas breck', 'claire overton', 'rachel kim', 'peter walsh', 'nadine cole', 'steven ford')
_OTHER_PERSON_TOKENS = {'diana', 'thomas', 'claire', 'rachel', 'peter', 'nadine', 'steven', 'walsh', 'breck', 'overton', 'kim', 'cole', 'ford'}
_ROLE_TOKENS = {'analyst', 'operations', 'ops', 'assistant'}

def check_analyst(text):
    # Template B-4 (SOP.pdf p.21) ends with 'Analyst: [Your name]'. The task
    # supplies only the role 'junior operations analyst' (never a personal
    # name), so accept role-based fills and reject fills naming other people.
    m = _ANALYST_FIELD_RE.search(text)
    if m is None:
        return 'missing Template B-4 Analyst field'
    value = m.group(1).strip()
    normalized = re.sub(r'[^a-z0-9]+', ' ', value.lower()).strip()
    tokens = set(normalized.split())
    if any(name in normalized for name in _OTHER_PERSON_NAMES) or (tokens & _OTHER_PERSON_TOKENS):
        return f"Analyst field must not identify another named person, got '{value}'"
    if not (tokens & _ROLE_TOKENS):
        return f"Analyst field must identify the filer by the task-supplied role (e.g. 'Junior Operations Analyst'), got '{value}'"
    return None

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path not provided.'}
    slack_path = Path(external_services_path) / 'slack_data.json'
    if not slack_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'slack_data.json not found.'}
    try:
        with open(slack_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to parse slack_data.json: {e}'}
    channels = data.get('channels', {})
    comp_urgent_id = None
    for ch_id, ch_info in channels.items():
        if isinstance(ch_info, dict) and ch_info.get('name', '').lower() == 'compliance-urgent':
            comp_urgent_id = ch_id
            break
    if comp_urgent_id is None:
        return {'pass': False, 'score': 0.0, 'feedback': '#compliance-urgent channel not found in slack_data.json.'}
    messages = data.get('messages', {}).get(comp_urgent_id, [])
    jira_key_pattern = re.compile(r'\b[A-Z]+-\d+\b')
    failures = []
    idx_0223 = set()
    idx_0228 = set()
    for idx, msg in enumerate(messages):
        if not isinstance(msg, dict):
            continue
        text = str(msg.get('text', ''))
        text_lower = text.lower()
        # Check for unwanted escalations
        if 'INTL-2026-0214' in text and ('exception' in text_lower or 'escalat' in text_lower):
            failures.append('Found message escalating INTL-2026-0214 in #compliance-urgent (should not exist)')
        if 'INTL-2026-0219' in text and ('exception' in text_lower or 'escalat' in text_lower):
            failures.append('Found message escalating INTL-2026-0219 in #compliance-urgent (should not exist)')
        # Check for 0223 message
        if 'INTL-2026-0223' in text:
            has_compliance_tag = '[compliance]' in text_lower or '[Compliance]' in text
            has_phrase = 'international wire control exception filed' in text_lower
            has_ops_key = bool(re.search(r'\bOPS-3\b|\bOPS-TRE-WIRE-INTL-2026-0223\b', text))
            has_comp_key = bool(jira_key_pattern.search(text)) and any(m.upper().startswith('COMP') for m in jira_key_pattern.findall(text))
            no_amount = '623,000' not in text and '623000' not in text
            no_bank = 'ing bank' not in text_lower
            analyst_issue = check_analyst(text)
            if has_compliance_tag and has_phrase and has_ops_key and has_comp_key and no_amount and no_bank and analyst_issue is None:
                idx_0223.add(idx)
            else:
                issues = []
                if not has_compliance_tag: issues.append('missing [Compliance]')
                if not has_phrase: issues.append('missing "International wire control exception filed"')
                if not has_ops_key: issues.append('missing OPS-3 (or OPS-TRE-WIRE-INTL-2026-0223)')
                if not has_comp_key: issues.append('missing COMP ticket key')
                if not no_amount: issues.append('contains wire amount 623,000')
                if not no_bank: issues.append('contains bank name ING Bank')
                if analyst_issue: issues.append(analyst_issue)
                if issues:
                    failures.append(f'INTL-2026-0223 message issues: {issues}')
        # Check for 0228 message
        if 'INTL-2026-0228' in text:
            has_compliance_tag = '[compliance]' in text_lower or '[Compliance]' in text
            has_phrase = 'international wire control exception filed' in text_lower
            has_ops_key = bool(re.search(r'\bOPS-4\b|\bOPS-TRE-WIRE-INTL-2026-0228\b', text))
            has_comp_key = bool(jira_key_pattern.search(text)) and any(m.upper().startswith('COMP') for m in jira_key_pattern.findall(text))
            no_amount = '312,000' not in text and '312000' not in text
            no_bank = 'bnp paribas' not in text_lower
            analyst_issue = check_analyst(text)
            if has_compliance_tag and has_phrase and has_ops_key and has_comp_key and no_amount and no_bank and analyst_issue is None:
                idx_0228.add(idx)
            else:
                issues = []
                if not has_compliance_tag: issues.append('missing [Compliance]')
                if not has_phrase: issues.append('missing "International wire control exception filed"')
                if not has_ops_key: issues.append('missing OPS-4 (or OPS-TRE-WIRE-INTL-2026-0228)')
                if not has_comp_key: issues.append('missing COMP ticket key')
                if not no_amount: issues.append('contains wire amount 312,000')
                if not no_bank: issues.append('contains bank name BNP Paribas')
                if analyst_issue: issues.append(analyst_issue)
                if issues:
                    failures.append(f'INTL-2026-0228 message issues: {issues}')
    if not idx_0223:
        failures.append('No valid #compliance-urgent message found for INTL-2026-0223')
    if not idx_0228:
        failures.append('No valid #compliance-urgent message found for INTL-2026-0228')
    if idx_0223 and idx_0228 and not any(i != j for i in idx_0223 for j in idx_0228):
        failures.append('INTL-2026-0223 and INTL-2026-0228 must be escalated in two distinct #compliance-urgent messages, not one combined message')
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'Slack #compliance-urgent issues: {failures}'}
    return {'pass': True, 'score': 1.0, 'feedback': 'Both INTL-2026-0223 and INTL-2026-0228 compliance-urgent messages verified correctly. No unwanted escalations found.'}

from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path not provided.'}
    slack_path = Path(external_services_path) / 'slack_data.json'
    jira_path = Path(external_services_path) / 'jira_state.json'
    if not slack_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'slack_data.json not found.'}
    if not jira_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'jira_state.json not found.'}
    try:
        with open(slack_path, 'r') as f:
            slack_data = json.load(f)
        with open(jira_path, 'r') as f:
            jira_data = json.load(f)
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Failed to parse files: {e}'}
    jira_issues = jira_data.get('issues', jira_data) if isinstance(jira_data, dict) else {}
    all_jira_keys = set()
    for k, v in jira_issues.items():
        all_jira_keys.add(k.upper())
        if isinstance(v, dict) and v.get('key'):
            all_jira_keys.add(str(v['key']).upper())
    channels = slack_data.get('channels', {})
    comp_urgent_id = None
    for ch_id, ch_info in channels.items():
        if isinstance(ch_info, dict) and ch_info.get('name', '').lower() == 'compliance-urgent':
            comp_urgent_id = ch_id
            break
    if comp_urgent_id is None:
        return {'pass': False, 'score': 0.0, 'feedback': '#compliance-urgent channel not found.'}
    messages = slack_data.get('messages', {}).get(comp_urgent_id, [])
    # Extract key from "Jira: KEY" field in B-4 template, falling back to any
    # non-OPS, non-INTL Jira key in the message if the template field is absent.
    jira_field_pattern = re.compile(r'[Jj]ira:\s*([A-Z][A-Z0-9]*-\d+)')
    any_key_pattern = re.compile(r'\b([A-Z][A-Z0-9]*-\d+)\b')
    failures = []
    for wire_id in ['INTL-2026-0223', 'INTL-2026-0228']:
        candidates = []
        for msg in messages:
            if not isinstance(msg, dict):
                continue
            text = str(msg.get('text', ''))
            if wire_id not in text or 'international wire control exception filed' not in text.lower():
                continue

            # Prefer the key from the explicit "Jira: KEY" field.
            comp_keys = jira_field_pattern.findall(text)
            if not comp_keys:
                # Fallback: any key that isn't an OPS- or INTL- pattern.
                all_keys = any_key_pattern.findall(text)
                comp_keys = [k for k in all_keys
                             if not k.upper().startswith('OPS-')
                             and not k.upper().startswith('INTL-')]
            missing_keys = [
                key for key in comp_keys if key.upper() not in all_jira_keys
            ]
            candidates.append((comp_keys, missing_keys))

        if not candidates:
            failures.append(f'No qualifying #compliance-urgent message found for {wire_id}')
            continue

        # A later B-4 post may correct an earlier stale/bad ticket reference.
        # Evaluate all candidates and accept the wire if any complete candidate
        # references at least one key and all of its keys exist.
        if not any(keys and not missing for keys, missing in candidates):
            details = [
                ('no compliance ticket key' if not keys else f'missing keys {missing}')
                for keys, missing in candidates
            ]
            failures.append(
                f'No qualifying Slack message for {wire_id} references an existing compliance ticket: {details}'
            )
    if failures:
        return {'pass': False, 'score': 0.0, 'feedback': f'COMP key cross-reference issues: {failures}'}
    return {'pass': True, 'score': 1.0, 'feedback': 'COMP ticket keys in Slack messages for INTL-2026-0223 and INTL-2026-0228 all exist in jira_state.json.'}
